antiPatterns.example:
// Avoid: ghost has no border
<ButtonGroup><Button variant="ghost">A</Button><Button>B</Button></ButtonGroup>

// Prefer: bordered variants
<ButtonGroup><Button variant="outline">A</Button><Button variant="outline">B</Button></ButtonGroup>

// Avoid: Save and Delete as joined segments
<ButtonGroup><Button>Save</Button><Button variant="destructive">Delete</Button></ButtonGroup>

// Prefer: separate buttons
<Button>Save</Button>
<Button variant="destructive">Delete</Button>
